style.css:
@-moz-document url-prefix("https://www.roblox.com"), url-prefix("https://www.web.roblox.com") {
/* navbar */
#header {
background-color: #fad5e5;
  border-color: #fad5e5;
}

 /* Search bar */
  .navbar-search, 
  .navbar-search input, 
  .navbar-search .new-dropdown-menu {
    background-color: #fff !important;
}

  /* profile sections */
  
   .dark-theme .section-content {
    background-color: #fad5e5; 
}
    .light-theme .section-content {
    background-color: #fad5e5; 
}
    
    /* pfps */
    .avatar-card-image, 
    .profile-avatar-left {
        background-color: #fce1e500 !important;
}

  .slide-switcher.games {
    color: #202227;
    background:transparent !important;
}

  /* Profile groups */
  .slide-switcher .slide-item-container .slide-item-container-left {
    background-color: #fad5e5 !important;
}
  .slide-switcher .slide-item-container .slide-item-container-right {
    background-color: #fad5e5 !important;
}

  /* Profile collections */
.dark-theme .layer {
  background-color: #fad5e5 !important;
}
    .light-theme .layer {
    background-color: #fad5e5 !important;
}

  /* Profile item scroll through  */
  .profile-accoutrements-page {
    border: 1px solid #ff96c3 !important;
}

  .page-active {
    background-color: #ff96c3 !important;
}

  /* play button */
  .btn-common-play-game-lg {
    background-color: #ff96c3 !important;
}
    
  /* play button hover */
   .btn-common-play-game-lg:hover, .light-theme .btn-common-play-game-lg:focus {
    background-color: #ffa3ca !important;
}

  /* Join event button */
  .btn-growth-xs {
    background-color: #ff96c3 !important;
}
  .btn-growth-xs:hover,
  .btn-growth-xs:focus {
    background-color: #ffa3ca !important;
}

  /* Chat */
  .chat-container .chat-main .chat-header {
    background-color: #ffa3ca !important;
}

  /* Avatar editor background */
  .avatar-back {
    background-image: url("https://i.imgur.com/qFmcbT0.png") !important;
}
    
    /* avatar editor navigation area */
    .rbx-tab .rbx-tab-heading {
    background-color: #ffa3ca !important;
}
    .dark-theme .rbx-tabs-horizontal .rbx-tab .rbx-tab-heading:hover {
    color: #ffd8de;
    background-color: #ffa3ca;
    box-shadow: inset 0 -4px #7272a6;
}
    .tab-horizontal-submenu {
        background-color: #ffd4da !important;
}
    
    .light-theme .rbx-tabs-horizontal .rbx-tab .rbx-tab-heading:hover {
    color: #ffd8de;
    background-color: #ffa3ca;
    box-shadow: inset 0 -4px #eba9ae;
}
    
    /* groups */
    .groups-list-sidebar {
    background-color: #fad5e5;
    border-left: 1px solid #fad5e5;
}
    .group-section-content {
    background-color: #fad5e5;
}
    
    .dark-theme .input-field {
        color: #ffffff !important;
}
    
    
    /* group wall */
    .group-details .group-wall .comment {
    background-color: #fad5e5;
}
        
  /* Friend list */
  .avatar-card-container {
    background-color: #fad5e5 !important;
}
    .dark-theme .avatar-card-btns {
    background:transparent !important;
}

  /* Left column (sidebar) */
  .rbx-left-col {
    background-color: #fad5e57d !important;
}
    
    
    /* inventory */
    .light-theme .rbx-tabs-vertical .category-tabs .menu-vertical {
    background-color: #fad5e5;
}

    
    /* website text */
    
    .dark-theme p, .dark-theme .text, .dark-theme .text-default, .dark-theme .text-secondary, .dark-theme .text-description, .dark-theme .text-label, .dark-theme .text-date-hint, .dark-theme .text-info, .dark-theme .text-footer {
    color: #ffffff;
}
        .light-theme p, .light-theme .text, .light-theme .text-default, .light-theme .text-secondary, .light-theme .text-description, .light-theme .text-label, .light-theme .text-date-hint, .light-theme .text-info, .light-theme .text-footer {
    color: #000;
}
  
/*Background*/
body, .content
{
     background: transparent !important;
}
.light-theme, .dark-theme, .nav-content
{
     width: 100% !important;
     height: 100% !important;
     background-attachment: fixed !important;
       background-size: cover !important; /* stretch width and height */
  background-repeat: no-repeat;
  background-position: center;
  background-image: url("data:image/avif;base64,") !important;
}
}
